begin;
do $$
declare p uuid; a uuid; b uuid; batch uuid; item_ids jsonb; line record; caught boolean;
begin
 p=public.warehouse_create_product(jsonb_build_object('sku','QA-LOC-'||gen_random_uuid(),'brand','SP','productNameCN','三库位数量测试','boxMultiplier',1,'cartonMultiplier',1));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',1,'location','Z-FIRST','quantity',4,'mode','set'));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',2,'location','A-SECOND','quantity',20,'mode','set'));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',3,'location','M-THIRD','quantity',6,'mode','set'));
 caught=false;
 begin perform public.warehouse_command('stock',jsonb_build_object('productId',p,'location','FOURTH','quantity',1,'mode','set')); exception when others then caught=true; end;
 if not caught then raise exception 'QA: fourth location was allowed'; end if;
 insert into public.orders(order_no,status,ai_status) values('QA-LOC-'||gen_random_uuid(),'uploaded','completed') returning id into a;
 perform public.warehouse_edit_item('add',jsonb_build_object('orderId',a,'productId',p,'qty',9,'unit','个'));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',a));
 batch=(public.warehouse_command('create_batch',jsonb_build_object('orderIds',jsonb_build_array(a),'requestId',gen_random_uuid(),'name','QA quantity priority','date',current_date))->>'id')::uuid;
 if (select requested from public.batch_lines where batch_id=batch and position=1)<>4 or (select requested from public.batch_lines where batch_id=batch and position=2)<>5 or (select count(*) from public.batch_lines where batch_id=batch)<>2 then raise exception 'QA: quantities not allocated in explicit location order'; end if;
 caught=false;
 begin perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('M-THIRD','Z-FIRST','A-SECOND'))); exception when others then caught=true; end;
 if not caught then raise exception 'QA: active batch locations reordered'; end if;
 select * into line from public.batch_lines where batch_id=batch and position=2;
 caught=false;
 begin perform public.warehouse_command('pick',jsonb_build_object('lineId',line.id,'quantity',line.requested)); exception when others then caught=true; end;
 if not caught then raise exception 'QA: second location picked before first'; end if;
 for line in select * from public.batch_lines where batch_id=batch order by position loop
  perform public.warehouse_command('pick',jsonb_build_object('lineId',line.id,'quantity',line.requested));
 end loop;
 perform public.warehouse_command('start_packing',jsonb_build_object('batchId',batch));
 select jsonb_agg(id) into item_ids from public.order_items where order_id=a;
 perform public.warehouse_command('pack',jsonb_build_object('orderId',a,'checkedItemIds',item_ids));
 if (select sum(quantity) from public.inventory_bins where product_id=p)<>21 then raise exception 'QA: packing deducted quantities twice'; end if;
 insert into public.orders(order_no,status,ai_status) values('QA-LOC-'||gen_random_uuid(),'uploaded','completed') returning id into a;
 insert into public.orders(order_no,status,ai_status) values('QA-LOC-'||gen_random_uuid(),'uploaded','completed') returning id into b;
 perform public.warehouse_edit_item('add',jsonb_build_object('orderId',a,'productId',p,'qty',7,'unit','个'));
 perform public.warehouse_edit_item('add',jsonb_build_object('orderId',b,'productId',p,'qty',5,'unit','个'));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',a));
 perform public.warehouse_command('ready',jsonb_build_object('orderId',b));
 batch=(public.warehouse_command('create_batch',jsonb_build_object('orderIds',jsonb_build_array(a,b),'requestId',gen_random_uuid(),'name','QA partial quantity','date',current_date))->>'id')::uuid;
 select * into line from public.batch_lines where batch_id=batch;
 perform public.warehouse_command('pick',jsonb_build_object('lineId',line.id,'quantity',10));
 perform public.warehouse_command('start_packing',jsonb_build_object('batchId',batch));
 select jsonb_agg(id) into item_ids from public.order_items where order_id=a;
 perform public.warehouse_command('pack',jsonb_build_object('orderId',a,'checkedItemIds',item_ids));
 select jsonb_agg(id) into item_ids from public.order_items where order_id=b;
 caught=false;
 begin perform public.warehouse_command('pack',jsonb_build_object('orderId',b,'checkedItemIds',item_ids)); exception when others then caught=true; end;
 if not caught then raise exception 'QA: insufficient quantity packed'; end if;
 perform public.warehouse_command('close_batch',jsonb_build_object('batchId',batch));
 if (select sum(quantity) from public.inventory_bins where product_id=p)<>14 or (select count(*) from public.inventory_bins where product_id=p)<>3 then raise exception 'QA: returns changed quantity or created extra records'; end if;
 perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('M-THIRD','Z-FIRST','A-SECOND')));
 batch=(public.warehouse_command('create_batch',jsonb_build_object('orderIds',jsonb_build_array(b),'requestId',gen_random_uuid(),'name','QA reordered priority','date',current_date))->>'id')::uuid;
 if (select location from public.batch_lines where batch_id=batch)<>'M-THIRD' then raise exception 'QA: reorder not used by allocation'; end if;
 perform public.warehouse_command('close_batch',jsonb_build_object('batchId',batch));
 caught=false;
 begin perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('Z-FIRST','A-SECOND'))); exception when others then caught=true; end;
 if not caught then raise exception 'QA: removed nonempty location'; end if;
 perform public.warehouse_command('reorder_locations',jsonb_build_object('productId',p,'locations',jsonb_build_array('M-THIRD','A-SECOND')));
 perform public.warehouse_command('stock',jsonb_build_object('productId',p,'position',3,'location','B-NEW','quantity',2,'mode','set'));
 if (select position from public.inventory_bins where product_id=p and location='Z-FIRST') is not null then raise exception 'QA: empty location not retired'; end if;
 if (select quantity_on_hand from public.inventory where product_id=p)<>16 then raise exception 'QA: quantity aggregate drift'; end if;
end $$;
set constraints all immediate;
rollback;
select 'PASS: quantity-only stock, max three locations, priority allocation, arbitrary pick quantities, order packing, returns, reordering and empty-location reuse' as result;
